describe('Touch Target Size - Mobile View', () => {
  beforeEach(() => {
    cy.visit('/mobile-form');
  });

  it('should display touch targets large enough for easy tapping on mobile', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="submit-button"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('have.css', 'width').and('include', '40px');
    cy.get('[data-testid="submit-button"]').should('have.css', 'height').and('include', '40px');
    cy.get('[data-testid="email-input"]').should('have.css', 'min-height').and('include', '40px');
    cy.get('[data-testid="password-input"]').should('have.css', 'min-height').and('include', '40px');
    cy.get('[data-testid="email-input"]').should('have.css', 'padding').and('include', '10px');
    cy.get('[data-testid="password-input"]').should('have.css', 'padding').and('include', '10px');
    cy.get('[data-testid="submit-button"]').should('be.enabled');
    cy.get('[data-testid="submit-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should handle edge case of small touch targets being disabled or hidden', () => {
    cy.viewport('iphone-12');
    cy.get('[data-testid="submit-button"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('be.disabled');
    cy.get('[data-testid="submit-button"]').should('have.attr', 'aria-disabled', 'true');
    cy.get('[data-testid="submit-button"]').should('not.have.css', 'width').and('not.include', '10px');
    cy.get('[data-testid="submit-button"]').should('not.have.css', 'height').and('not.include', '10px');
    cy.get('[data-testid="email-input"]').should('have.css', 'min-height').and('include', '40px');
    cy.get('[data-testid="email-input"]').should('have.css', 'padding').and('include', '10px');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').type('test@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
    cy.get('[data-testid="submit-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
